  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 24px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 16px;
  background: var(--theme-background-color);
}

.mtd-quiz-banner-copy {
  min-width: 0;
}

