  margin: 0;
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 16px;
  line-height: 1.4;
}

.mtd-quiz-banner-cta.score-button {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 12px 24px;
  border-radius: 999px;
  font-family: inherit;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.mtd-quiz-section {
  background: var(--theme-background-color);
  padding: 32px 0 48px;
  scroll-margin-top: 80px;
}

.mtd-quiz-frame {
  display: block;
  width: 100%;
  min-height: 640px;
  border: 0;
  border-radius: 16px;
  background: var(--theme-background-color);
}

/* Variant A: the quiz in a dialog opened from the hero CTA. */
.mtd-quiz-modal[hidden] {
  display: none;
}

