/* One consistent look for the card class (not a .score-button — the quiz's
   own component). Hover/focus/active are defined once here for every card. */
main.solution-finder-host [class*="StyledButton"]:hover {
  border-color: #fff;
}
main.solution-finder-host [class*="StyledButton"]:focus-visible {
  outline: 3px solid #00d639;
  outline-offset: 2px;
}
main.solution-finder-host [class*="StyledButton"]:active {
  border-color: #fff;
}
main.solution-finder-host [class*="StyledButton"] [role="img"] {
  width: 60px;
  height: 60px;
  display: block;
  flex: 0 0 auto;
}
main.solution-finder-host [class*="StyledButton"] [role="img"] svg {
  width: 60px;
  height: 60px;
  display: block;
  fill: #fff;
}
main.solution-finder-host [class*="StyledButton"] [class*="klpehu"],
main.solution-finder-host [class*="StyledButton"] [class*="sc-fsYeqr"] {
  margin: 0;
  font: 400 18px/28.8px "Sage Text", "Sage UI", sans-serif;
  color: rgba(255, 255, 255, 0.9);
  text-align: center;
  width: 100%;
}

/* Answers row: centred, gap 24. */
main.solution-finder-host [class*="cdfGlC"],
main.solution-finder-host [class*="StyledQuestions"] [class*="sc-dmXXqF"]:has(> [class*="StyledButton"]) {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 24px;
